const ContactForm = () => {
  const [formData, setFormData] = useState({
    fullName: '',
    email: '',
    phone: ''
  });

  const [errors, setErrors] = useState({});
  const [submitted, setSubmitted] = useState(false);

  const fullNameRef = useRef(null);
  const emailRef = useRef(null);
  const phoneRef = useRef(null);

  const validateEmail = (email) => {
    return String(email)
      .toLowerCase()
      .match(
        /^(([^<>()[\]\\.,;:\s@"]+(\.[^<>()[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/
      );
  };

  const validatePhone = (phone) => {
    if (!phone) return true;
    return phone.match(/^\(\d{3}\)\s\d{3}-\d{4}$/);
  };

  const validate = () => {
    const newErrors = {};
    if (!formData.fullName.trim()) {
      newErrors.fullName = 'Full name is required';
    }
    if (!formData.email.trim()) {
      newErrors.email = 'Email address is required';
    } else if (!validateEmail(formData.email)) {
      newErrors.email = 'Please enter a valid email address';
    }
    if (formData.phone && !validatePhone(formData.phone)) {
      newErrors.phone = 'Please match the requested format: (555) 555-5555';
    }
    return newErrors;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    const newErrors = validate();
    setErrors(newErrors);

    if (Object.keys(newErrors).length === 0) {
      setSubmitted(true);
      console.log('Form submitted:', formData);
    } else {
      // Focus the first invalid control
      if (newErrors.fullName) {
        fullNameRef.current.focus();
      } else if (newErrors.email) {
        emailRef.current.focus();
      } else if (newErrors.phone) {
        phoneRef.current.focus();
      }
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    // Clear error when user starts typing
    if (errors[name]) {
      setErrors(prev => ({ ...prev, [name]: null }));
    }
  };

  if (submitted) {
    return (
      <div role="status" aria-live="polite" className="success-message">
        <h2>Thank you!</h2>
        <p>Your support request has been submitted successfully. We'll get back to you soon.</p>
        <button onClick={() => setSubmitted(false)}>Send another message</button>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <div className="form-field">
        <label htmlFor="fullName">Full Name *</label>
        <input
          type="text"
          id="fullName"
          name="fullName"
          value={formData.fullName}
          onChange={handleChange}
          ref={fullNameRef}
          required
          aria-required="true"
          aria-invalid={!!errors.fullName}
          aria-describedby={errors.fullName ? "fullName-error" : undefined}
          autoComplete="name"
        />
        <div id="fullName-error" className="error-message" role="alert">
          {errors.fullName}
        </div>
      </div>

      <div className="form-field">
        <label htmlFor="email">Email Address *</label>
        <input
          type="email"
          id="email"
          name="email"
          value={formData.email}
          onChange={handleChange}
          ref={emailRef}
          required
          aria-required="true"
          aria-invalid={!!errors.email}
          aria-describedby={errors.email ? "email-error" : undefined}
          autoComplete="email"
        />
        <div id="email-error" className="error-message" role="alert">
          {errors.email}
        </div>
      </div>

      <div className="form-field">
        <label htmlFor="phone">Phone Number (Optional)</label>
        <input
          type="tel"
          id="phone"
          name="phone"
          value={formData.phone}
          onChange={handleChange}
          ref={phoneRef}
          aria-invalid={!!errors.phone}
          aria-describedby={errors.phone ? "phone-error phone-helper" : "phone-helper"}
          autoComplete="tel"
        />
        <p id="phone-helper" className="helper-text">
          Format: (555) 555-5555
        </p>
        <div id="phone-error" className="error-message" role="alert">
          {errors.phone}
        </div>
      </div>

      <button type="submit">Submit Support Request</button>
    </form>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<ContactForm />);
